mapper.select:
select p.img as image,p.parent_id,p.name,p.sex,s.name as studentName,s.clazz as studentClazz,p.phone,p.password,s.student_id as studentId,s.status,s.grade,s.clazz from parent p join student s on p.parent_id = s.parent_id
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select p.img as image,p.parent_id,p.name,p.sex,s.name as studentName,s.clazz as studentClazz,p.phone,p.password from parent p join student s on p.parent_id = s.parent_id where p.name like CONCAT('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select p.img as image,p.parent_id,p.name,p.sex,s.name as studentName,s.clazz as studentClazz,p.phone,p.password from parent p join student s on p.parent_id = s.parent_id where p.parent_id like CONCAT('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select p.img as image,p.parent_id,p.name,p.sex,s.name as studentName,s.clazz as studentClazz,p.phone,p.password from parent p join student s on p.parent_id = s.parent_id where p.student_id like CONCAT('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select p.img as image,p.parent_id,p.name,p.sex,s.name as studentName,s.clazz as studentClazz,p.phone,p.password,s.status from parent p join student s on p.parent_id = s.parent_id where p.sex like CONCAT('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select p.img as image,p.parent_id,p.name,p.sex,s.name as studentName,s.clazz as studentClazz,p.phone,p.password,s.student_id as studentId,s.status,s.grade,s.clazz, p.create_time, p.update_time from parent p join student s on p.parent_id = s.parent_id
and s.clazz like concat('%', #{clazz}, '%')
and p.name like CONCAT('%',#{PName},'%')
and S.name like CONCAT('%',#{SName},'%')
and s.student_id like CONCAT('%',#{Sid},'%')
AND p.phone = #{phone}
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}
